import { describe, expect, test } from "bun:test";
import { renderBundledSkills, renderReadmeSkills } from "./bundled-skills";

const BEGIN =
	"<!-- BEGIN bundled-skills (generated by `bun run generate:skills`) -->";
const END = "<!-- END bundled-skills -->";

describe("renderReadmeSkills", () => {
	test("replaces only the text between the markers", () => {
		const readme = `# Title\n\n${BEGIN}\n- \`old\`: Gone\n${END}\n\nAfter\n`;
		expect(
			renderReadmeSkills(readme, [
				{ name: "10x", description: "Audit" },
				{ name: "page", description: "Publish" },
			]),
		).toBe(
			`# Title\n\n${BEGIN}\n- \`10x\`: Audit\n- \`page\`: Publish\n${END}\n\nAfter\n`,
		);
	});

	test("is null without the markers", () => {
		expect(renderReadmeSkills("# Title\n", [])).toBeNull();
	});
});

test("renderBundledSkills keeps names and descriptions as string literals", () => {
	expect(
		renderBundledSkills([{ name: "10x", description: 'Say "hi"' }]),
	).toContain('\t\tname: "10x",\n\t\tdescription: "Say \\"hi\\"",');
});
